import java.util.*;
import java.io.*;

public class Main {
    static final int N = 12;
    static final int INF = 1000000009;
    static final int[] dir_x = {0, 1, 0, -1};
    static final int[] dir_y = {1, 0, -1, 0};

    static int n, t;
    static char[][] mapA = new char[N][N];
    static char[][] mapB = new char[N][N];

    static int start_x, start_y;
    static int[][] distance_map = new int[N][N];

    static boolean[][][][][] residual = new boolean[N * 6][N][N][N][N];
    static boolean[][] can_reach = new boolean[N][N][N][N];

    static int[][] g = new int[2 * N * N][2 * N * N];

    static int[] p = new int[2 * N * N];
    static boolean[] visited_q = new boolean[2 * N * N];

    static class Coord {
        int row, col;
        Coord() {}
        Coord(int _r, int _c) {
            this.row = _r;
            this.col = _c;
        }
    }

    static void run_bfs(int[][] d, int sx, int sy) {
        boolean[][] visited = new boolean[N][N];
        for (int i = 0; i < n; ++i)
            Arrays.fill(d[i], INF);
        Queue<Coord> q = new LinkedList<>();
        visited[sx][sy] = true;
        d[sx][sy] = 0;
        q.offer(new Coord(sx, sy));
        while (!q.isEmpty()) {
            Coord curr = q.poll();
            for (int d_idx = 0; d_idx < 4; ++d_idx) {
                int next_row = curr.row + dir_x[d_idx];
                int next_col = curr.col + dir_y[d_idx];
                if (next_row >= 0 && next_row < n && next_col >= 0 && next_col < n
                        && !visited[next_row][next_col]
                        && mapA[next_row][next_col] >= '0'
                        && mapA[next_row][next_col] <= '9') {
                    visited[next_row][next_col] = true;
                    d[next_row][next_col] = d[curr.row][curr.col] + 1;
                    q.offer(new Coord(next_row, next_col));
                }
            }
        }
    }

    static boolean flow_bfs() {
        Arrays.fill(visited_q, false);
        Arrays.fill(p, 0);
        Queue<Integer> q = new LinkedList<>();
        visited_q[0] = true;
        q.offer(0);
        while (!q.isEmpty()) {
            int curr_node = q.poll();
            if (curr_node == 2 * n * n + 1)
                return true;
            for (int h = 0; h <= 2 * n * n + 1; ++h) {
                if (g[curr_node][h] != 0) {
                    if (!visited_q[h]) {
                        visited_q[h] = true;
                        p[h] = curr_node;
                        q.offer(h);
                    }
                }
            }
        }
        return false;
    }

    static void process(Scanner sc) {
        n = sc.nextInt();
        t = sc.nextInt();
        for (int i = 0; i < n; ++i)
            mapA[i] = sc.next().toCharArray();
        for (int i = 0; i < n; ++i)
            mapB[i] = sc.next().toCharArray();
        start_x = sc.nextInt();
        start_y = sc.nextInt();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (mapA[i][j] == 'Z') {
                    start_x = i;
                    start_y = j;
                }
        run_bfs(distance_map, start_x, start_y);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if ('0' <= mapA[i][j] && mapA[i][j] <= '9')
                    residual[0][i][j][i][j] = true;

        for (int step = 0; step < t; ++step) {
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y) {
                            if (!residual[step][sx][sy][x][y]) continue;
                            if (distance_map[x][y] <= step) continue;
                            for (int d_idx = 0; d_idx < 4; ++d_idx) {
                                int hx = x + dir_x[d_idx];
                                int hy = y + dir_y[d_idx];
                                if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= mapA[hx][hy] && mapA[hx][hy] <= '9') {
                                    if (distance_map[hx][hy] >= step + 1)
                                        residual[step + 1][sx][sy][hx][hy] = true;
                                }
                            }
                        }
        }
        for (int step = 0; step <= t; ++step)
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y)
                            if (residual[step][sx][sy][x][y])
                                can_reach[sx][sy][x][y] = true;

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                if ('0' <= mapA[x1][y1] && mapA[x1][y1] <= '9')
                    g[0][x1 * n + y1 + 1] = mapA[x1][y1] - '0';

        for (int x2 = 0; x2 < n; ++x2)
            for (int y2 = 0; y2 < n; ++y2)
                if ('0' <= mapB[x2][y2] && mapB[x2][y2] <= '9')
                    g[n * n + x2 * n + y2 + 1][2 * n * n + 1] = mapB[x2][y2] - '0';

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2) {
                        if (!('0' <= mapA[x1][y1] && mapA[x1][y1] <= '9')) continue;
                        if (!('0' <= mapA[x2][y2] && mapA[x2][y2] <= '9')) continue;
                        if (!can_reach[x1][y1][x2][y2]) continue;
                        g[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                    }

        while (flow_bfs()) {
            int flow_val = INF;
            for (int i = 2 * n * n + 1; i != 0; i = p[i]) {
                flow_val = Math.min(flow_val, g[p[i]][i]);
            }
            for (int i = 2 * n * n + 1; i != 0; i = p[i]) {
                g[p[i]][i] -= flow_val;
                g[i][p[i]] += flow_val;
            }
        }

        int total = 0;
        for (int i = 0; i <= 2 * n * n + 1; ++i)
            total += g[i][0];

        System.out.println(total);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        process(sc);
        sc.close();
    }
}
